    if (event.key === "ArrowLeft") nextIndex = (currentIndex + MODES.length - 1) % MODES.length;
    if (event.key === "ArrowRight") nextIndex = (currentIndex + 1) % MODES.length;
    if (event.key === "Home") nextIndex = 0;
    if (event.key === "End") nextIndex = MODES.length - 1;
    setMode(MODES[nextIndex]);
    dom.modeTabs[nextIndex].focus();
  });
});

dom.seedButtons.forEach(button => {
  button.addEventListener("click", () => {
    const retainedMode = state.mode;
    reset(Number(button.dataset.seed));
    activateMode(retainedMode, true, false);
    dom.liveStatus.textContent = `Seed ${button.dataset.seed} loaded`;
  });
});

dom.playButton.addEventListener("click", togglePlayback);
dom.replayButton.addEventListener("click", replayMotion);
dom.timeline.addEventListener("input", event => seek(Number(event.currentTarget.value)));

dom.instrumentCanvas.addEventListener("pointerdown", handleInstrumentPointerDown);
dom.instrumentCanvas.addEventListener("pointermove", handleInstrumentPointerMove);
dom.instrumentCanvas.addEventListener("pointerup", handleInstrumentPointerUp);
dom.instrumentCanvas.addEventListener("pointercancel", handleInstrumentPointerUp);
dom.instrumentCanvas.addEventListener("pointerleave", () => applyInstrumentAction({ type: "leave" }));
dom.instrumentCanvas.addEventListener("keydown", handleInstrumentKeydown);

document.addEventListener("keydown", handleGlobalKeydown);
window.addEventListener("resize", handleResize, { passive: true });
document.addEventListener("visibilitychange", () => {
  const now = performance.now();
  state.lastFrame = now;
  if (document.hidden && state.playing) {
    state.motionTime = Math.min(DURATION, state.playbackStartedTime + Math.max(0, now - state.playbackStartedAt));

          const modePass = MODES.every(mode => setMode(mode) && state.mode === mode);
          record("all three modes", modePass, modePass ? "poster, motion, and instrument were reached" : `stopped at ${state.mode}`);

          seek(4321.125);
          record("exact motion seeking", state.motionTime === 4321.125, `motion time is ${state.motionTime}`);

          seek(-50);
          const lowerBoundary = state.motionTime === 0;
          seek(DURATION + 750);
          const upperBoundary = state.motionTime === DURATION && state.playing === false;
          record("12-second timeline boundary", lowerBoundary && upperBoundary, `clamped to 0 and ${state.motionTime}; playback stopped`);

          setMode("instrument");
          const before = JSON.stringify(snapshot().instrument);
          applyInstrumentAction({ type: "press", x: .31, y: .58 });
          applyInstrumentAction({ type: "move", x: .67, y: .36, dx: .18, dy: -.11, dragging: true });
          applyInstrumentAction({ type: "release", x: .67, y: .36 });
          const interactionSnapshot = snapshot().instrument;
          const numericValues = [
            interactionSnapshot.focus.x,
            interactionSnapshot.focus.y,
            interactionSnapshot.energy,
            interactionSnapshot.seamPhase,
            ...interactionSnapshot.offsets
          ];
          const changed = before !== JSON.stringify(interactionSnapshot);
          const finitePass = changed && numericValues.every(Number.isFinite);
          record("finite interaction state", finitePass, finitePass ? "real press, drag, and release changed only finite numeric state" : "interaction failed or produced a non-finite value");

          let jsonPass = false;
          try {
            jsonPass = typeof JSON.stringify(snapshot()) === "string";
          } catch (error) {
            jsonPass = false;
          }
          record("JSON-safe snapshot", jsonPass, jsonPass ? "snapshot serialized successfully" : "snapshot did not serialize");
        } catch (error) {
          record("self-test execution", false, error instanceof Error ? error.message.slice(0, 120) : "unknown failure");
        } finally {
          state.seed = saved.seed;
          state.identity = deriveIdentity(saved.seed);
          state.instrument = saved.instrument;
          state.motionTime = saved.motionTime;
          state.lastFrame = performance.now();
          state.playbackStartedAt = state.lastFrame;
          state.playbackStartedTime = saved.motionTime;
          renderPoster();
          activateMode(saved.mode, false, false);
          state.playing = saved.playing && saved.motionTime < DURATION;
          syncSeedControls();
          syncMotionControls();
          if (saved.mode === "motion") renderMotion();
          if (saved.mode === "instrument") renderInstrument();
          dom.modeWipe.classList.remove("is-moving");
        }

        return { passed: tests.every(test => test.pass), tests };
      }

      function syncSeedControls() {
        dom.seedButtons.forEach(button => {
          button.setAttribute("aria-pressed", String(Number(button.dataset.seed) === state.seed));
        });
        dom.seedReadout.textContent = String(state.seed);
      }

      function togglePlayback() {
        if (state.motionTime >= DURATION) state.motionTime = 0;
        state.playing = !state.playing;
        state.lastFrame = performance.now();
        state.playbackStartedAt = state.lastFrame;
      dom.instrumentCanvas.addEventListener("pointercancel", handleInstrumentPointerUp);
      dom.instrumentCanvas.addEventListener("pointerleave", () => applyInstrumentAction({ type: "leave" }));
      dom.instrumentCanvas.addEventListener("keydown", handleInstrumentKeydown);

      document.addEventListener("keydown", handleGlobalKeydown);
      window.addEventListener("resize", handleResize, { passive: true });
      document.addEventListener("visibilitychange", () => {
        const now = performance.now();
        state.lastFrame = now;
        if (document.hidden && state.playing) {
          state.motionTime = Math.min(DURATION, state.playbackStartedTime + Math.max(0, now - state.playbackStartedAt));
          state.playing = false;
          syncMotionControls();
        }
      });
      reducedMotionQuery.addEventListener?.("change", event => {
        state.reducedMotion = event.matches;
        if (event.matches) state.playing = false;
        syncMotionControls();
      });

      document.title = MODEL_NAME;
      window.__LIVING_IDENTITY__ = Object.freeze({ reset, setMode, seek, snapshot, runSelfTest });
      reset(DEFAULT_SEED);
      requestAnimationFrame(animationLoop);
    })();
