  }

  .mode-number {
    display: none;
  }

  .motion-hud {
    top: 14px;
    right: 14px;
    left: 14px;
  }

  .motion-duration span {
    display: none;
  }

  .instrument-title {
    font-size: 24px;
  }

  .instrument-status {
    gap: 10px;
  }
}

@media (max-height: 600px) and (orientation: landscape) {
  :root {
    --header-h: 56px;
  }

  .app-header {
    grid-template-areas: "model nav seed";
    grid-template-columns: minmax(72px, 1fr) minmax(240px, 300px) auto;
    grid-template-rows: 56px;
    gap: 8px;
    padding-right: max(8px, env(safe-area-inset-right));
    padding-left: max(8px, env(safe-area-inset-left));
  }

  .model-lockup {
    grid-area: model;
  }

  .mode-nav {
    grid-area: nav;
    min-width: 0;
  }

  .seed-switcher {
    grid-area: seed;
  }

  .seed-button {
    width: 36px;
    height: 36px;
  }

  .mode-tab {
    padding: 0 4px;
  }

  .poster-frame {
    width: min(70vw, calc((100dvh - 76px) * .8));
  }

  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
  transition: background-color .2s ease, color .2s ease, border-color .2s ease;
}

.transport-button:hover {
  color: var(--ink);
  border-color: var(--paper);
  background: var(--paper);
}

.transport-button.primary {
  color: var(--ink);
  border-color: var(--burn);
  background: var(--burn);
}

.transport-button.primary:hover {
  border-color: var(--paper);
  background: var(--paper);
}

.timeline-wrap {
  position: relative;
  display: grid;
  align-items: center;
  height: 44px;
  padding: 0 2px;
}

.timeline {
  width: 100%;
  height: 18px;
  margin: 0;
  appearance: none;
  background: transparent;
  cursor: ew-resize;
}

.timeline::-webkit-slider-runnable-track {
  height: 2px;
  background: linear-gradient(to right, var(--burn) 0 var(--progress, 0%), rgba(242, 243, 240, .25) var(--progress, 0%) 100%);
}

.timeline::-moz-range-track {
  height: 2px;
  background: rgba(242, 243, 240, .25);
}

.timeline::-moz-range-progress {
  height: 2px;
  background: var(--burn);
}

.timeline::-webkit-slider-thumb {
  width: 10px;
  height: 18px;
  margin-top: -8px;
  appearance: none;
  border: 0;
  font-weight: 700;
}

.instrument-event-line {
  position: absolute;
  bottom: 0;
  left: 0;
  max-width: min(52vw, 620px);
  color: var(--paper);
  font-family: "Arial Narrow", "Helvetica Neue", Arial, sans-serif;
  font-size: clamp(9px, .8vw, 12px);
  font-weight: 800;
  letter-spacing: .09em;
  line-height: 1.5;
  text-transform: uppercase;
}

.instrument-event-line em {
  color: var(--paper);
  font-style: normal;
  text-decoration: underline;
  text-decoration-color: var(--burn);
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
}

@media (max-width: 1120px) {
  .poster-side-note {
    display: none;
  }

  .poster-frame {
    width: min(720px, 82vw, calc((100dvh - var(--header-h) - 34px) * .8));
  }
}

@media (max-width: 920px) and (min-width: 761px) {
  .app-header {
    gap: 16px;
  }

  .mode-nav {
    min-width: 300px;
  }

  .seed-label,
  .seed-readout {
    display: none;
  }
}

@media (max-width: 760px) {
  :root {
    --header-h: 106px;
  }

  .app-header {
    grid-template-areas:
      "model seed"
      "nav nav";
    grid-template-columns: 1fr auto;

